def fitness_number_kind(chromosome, target):
    x = chromosome[0]
    if target == "zero":
        return abs(x)
    elif target == "even":
        return (1 if x == 0 else 0) + (x % 2)
    elif target == "odd":
        return (1 if x == 0 else 0) + (1 - (x % 2))
    else:
        raise ValueError("Unknown target")

