def fitness_sign_type(chromosome, target):
    x = chromosome[0]
    if target == "positive":
        return max(0, 0 - x + 1) if x <= 0 else 0
    elif target == "negative":
        return max(0, x + 1) if x >= 0 else 0
    elif target == "zero":
        return max(0, abs(x)) if x != 0 else 0
    else:
        raise ValueError("Unknown target")

