# Notes: Fitness returns 0 only when the input string exactly matches the target's conditions. For palindromes, distance is calculated as the number of character mismatches. For length conditions, distance is the difference between required length and actual length. For 'other', distance is the sum of distances to all mutually exclusive conditions.
# ================================================================================

def fitness_string_category(chromosome, target):
    s = chromosome[0]
    if target not in ['empty', 'long_palindrome', 'short_palindrome', 'long_non_palindrome', 'other']:
        raise ValueError(f"Unknown target: {target}")

    def is_palindrome(s):
        return s == s[::-1]

    def palindrome_distance(s):
        dist = 0
        for i in range(len(s)//2):
            if s[i] != s[-(i+1)]:
                dist += 1
        return dist

    if target == 'empty':
        return 0 if len(s) == 0 else 1

    if target == 'long_palindrome':
        pal_dist = palindrome_distance(s)
        len_dist = max(0, 4 - len(s))
        return pal_dist + len_dist

    if target == 'short_palindrome':
        pal_dist = palindrome_distance(s)
        len_dist = max(0, len(s) - 3)
        return pal_dist + len_dist

    if target == 'long_non_palindrome':
        pal_dist = 1 if is_palindrome(s) else 0
        len_dist = max(0, 6 - len(s))
        return pal_dist + len_dist

    if target == 'other':
        empty_dist = 1 if len(s) == 0 else 0
        pal_dist = 1 if is_palindrome(s) else 0
        len_dist = 1 if len(s) > 5 else 0
        return empty_dist + pal_dist + len_dist

    return float('inf')

